from mk import *
R=[]
R.append((9426064,"Cupcake Cokelat Vegan Sehat",
"Cupcake cokelat vegan paling sehat, tetapi rasanya sungguh luar biasa!",
"12 cupcake","1 porsi",
[("Bahan Basah","6 sendok makan puree ubi jalar dari sekitar 1 ubi jalar berdaging oranye ukuran sedang yang dipanggang"),("Bahan Basah","¾ cangkir susu almond atau susu nabati lainnya"),("Bahan Basah","½ cangkir sirup maple"),("Bahan Kering","150 gram tepung almond blanched, sekitar 1.5 cangkir"),("Bahan Kering","130 gram tepung oat, sekitar 1.5 cangkir"),("Bahan Kering","⅓ cangkir bubuk kakao mentah tanpa pemanis"),("Bahan Kering","2.5 sendok teh baking powder"),("Bahan Kering","¼ sendok teh garam laut"),("Untuk Frosting","1 cangkir kacang hitam, matang atau kalengan"),("Untuk Frosting","2 sendok makan bubuk kakao mentah tanpa pemanis"),("Untuk Frosting","¼ cangkir sirup maple")],
[("Sebelum Anda mulai","Untuk menyiapkan ubi jalar: Panaskan oven terlebih dahulu hingga 425°F/218°C. Lalu sikat ubi hingga bersih dan letakkan di atas loyang lalu panggang selama sekitar 35-45 menit, atau hingga mudah ditusuk garpu. ATAU, jika Anda memiliki air fryer, Anda dapat menggorengnya dengan air fryer menggunakan metode ini untuk menghemat waktu. Sisihkan."),("Untuk cupcake","Panaskan oven terlebih dahulu hingga 350°F/176°C dan alasi cetakan muffin dengan cup kertas roti."),("Untuk cupcake","Kupas ubi jalar atau keruk dagingnya dan tumbuk di atas piring. Lalu takar enam sendok makan (tidak lebih) untuk digunakan dalam adonan dan masukkan ke dalam mangkuk besar. Masukkan susu dan sirup maple ke dalam mangkuk yang sama dan kocok hingga tercampur."),("Untuk cupcake","Selanjutnya, masukkan semua bahan kering ke dalam mangkuk yang sama dan aduk hingga tercampur."),("Untuk cupcake","Bagi adonan ke 12 cetakan muffin dan panggang selama 20-22 menit, atau hingga tusuk gigi yang ditusukkan di tengah keluar bersih. Sisihkan hingga benar-benar dingin sebelum diberi frosting."),("Untuk frosting","Masukkan semua bahan frosting ke dalam blender berkecepatan tinggi atau food processor dan blender hingga halus. Setelah cupcake dingin, gunakan kantong piping untuk memberi frosting dan selamat menikmati.")],
["Timbang tepung Anda untuk hasil yang paling akurat. Saya sangat menyarankan agar tidak mengandalkan takaran cangkir saat membuat kue. Jika Anda tidak memiliki timbangan dapur, Anda dapat menyendok tepung ke dalam cangkir takar dan menggunakan pisau untuk meratakan kelebihannya, dengan hasil yang serupa. Jangan menyendok langsung dari kantong! Gunakan baking powder yang segar dan aktif. Baking powder yang sudah dibuka di lemari dapur selama lebih dari 6 bulan dapat mulai kehilangan keefektifannya. Jika memungkinkan, panggang ubi jalar Anda satu hari sebelumnya, atau beberapa jam sebelum Anda berencana membuat cupcake. Biarkan cupcake dingin di cetakan muffin setidaknya 10 menit sebelum disentuh. Lalu pindahkan ke rak pendingin hingga benar-benar dingin SEBELUM diberi frosting. Cupcake ini paling enak pada hari ke-1 hingga ke-2, tetapi Anda dapat menyimpan sisanya di lemari es hingga 4 hari. Simpan dalam wadah tertutup untuk menjaga kelembapan. Atau bekukan cupcake tanpa frosting dalam wadah kedap udara yang aman untuk freezer hingga 3 bulan. Saya menyarankan membuat frosting segar sebelum disajikan."],[]))
R.append((9426702,"Pizza Nangka BBQ dengan Pilihan Instant Pot",
"Nangka suwir dan keju mozzarella vegan adalah kombinasi luar biasa pada pizza nangka ini! Beraroma asap dan terurai seperti daging babi suwir, dengan saus BBQ buatan sendiri yang luar biasa, tetapi 100% VEGAN!",
"4 porsi","1 porsi",
[("Untuk Nangka","1 kaleng 20 ons nangka muda hijau dalam air garam atau air, BUKAN sirup"),("Untuk Nangka","½ cangkir saus tomat"),("Untuk Nangka","¼ cangkir cuka sari apel"),("Untuk Nangka","¼ cangkir air"),("Untuk Nangka","2 sendok makan tamari atau kecap asin jika tidak menghindari gluten"),("Untuk Nangka","1 sendok makan sirup maple"),("Untuk Nangka","1 sendok makan mustard kuning"),("Untuk Nangka","1 sendok teh paprika asap"),("Untuk Nangka","1 sendok teh bubuk bawang putih"),("Untuk Nangka","1 sendok teh bubuk bawang bombai"),("Untuk Pizza","2 roti pipih multigrain 12 inci atau roti pipih/adonan pilihan dengan ukuran serupa"),("Untuk Pizza","½ resep keju mozzarella vegan"),("Untuk Pizza","¼ cangkir bawang merah, diiris tipis")],
["Mulailah dengan membuat keju mozzarella vegan Anda. Lalu dinginkan di lemari es sementara Anda menyiapkan sisanya, agar sedikit mengeras sehingga lebih mudah disendok ke atas kulit pizza.","Tiriskan dan bilas nangka Anda dengan sangat baik untuk menghilangkan rasa air garam. Lalu pindahkan ke food processor dan pulse hingga terurai. Jangan memproses berlebihan, Anda menginginkan potongan kasar, bukan cincangan. Atau, Anda dapat memindahkan nangka ke talenan dan menyuwir potongannya dengan jari atau dua garpu. Sisihkan.",("Untuk Memasak Nangka di Atas Kompor","Kocok semua bahan saus dalam mangkuk kecil dan sisihkan."),("Untuk Memasak Nangka di Atas Kompor","Letakkan nangka suwir dalam wajan dan tuang saus di atasnya. Tumis dengan api sedang, aduk sesekali, hingga saus sebagian besar terserap. Ini akan memakan waktu sekitar 8-10 menit."),("Untuk Memasak Nangka di Instant Pot Anda","Masukkan nangka suwir dan semua bahan saus ke dalam Instant Pot Anda. (Tidak perlu mengocok saus terlebih dahulu dalam mangkuk terpisah.) Aduk rata, tutup penutup dan atur katup ke posisi penyegelan. Masak dengan tekanan tinggi selama 3 menit dan biarkan Instant Pot Anda melepaskan tekanan secara alami, yang akan memakan waktu sekitar 10 menit. Jika belum terlepas sepenuhnya setelah 10 menit, lepaskan sisa tekanan secara cepat."),("Untuk Merakit Pizza","Panaskan oven terlebih dahulu hingga 425 derajat F dan alasi loyang besar yang muat untuk kedua roti pipih dengan kertas roti, atau gunakan dua loyang yang lebih kecil."),("Untuk Merakit Pizza","Bagi nangka ke dua roti pipih Anda, dan sendok mozzarella vegan menggunakan pencetak bola melon atau sendok teh. Letakkan keju di seluruh pizza dan taburi bawang merah di atasnya. Panggang selama 13-18 menit, atau hingga tepi keemasan dan mozzarella sedikit meleleh.")],
["Pastikan membilas nangka dengan sangat baik untuk menghilangkan sebanyak mungkin rasa air garam. Jangan memproses nangka berlebihan, jika Anda menggunakan food processor. Cukup pulse hingga terurai, tanpa menjadi cincangan. Anda menginginkan potongan yang lebih kasar. Jika ada potongan utuh yang tidak terurai, sobek dengan tangan agar potongan lainnya tidak terproses berlebihan. Pizza nangka Anda dapat disimpan di lemari es selama 3-4 hari dalam wadah tertutup. Anda dapat memanaskannya kembali di oven atau oven kecil."],[]))
R.append((9429573,"Muffin Pisang Bayam",
"Hanya dengan 1 mangkuk Anda dapat membuat muffin bayam pisang yang empuk dan lezat. Banyak buah dan sayuran tersembunyi untuk sarapan atau hidangan penutup yang sehat.",
"36 muffin mini","1 porsi",
[("Bahan Kering","1 cangkir tepung beras cokelat atau beras cokelat* (lihat catatan)"),("Bahan Kering","1 cangkir tepung oat atau oat gulung** bebas gluten jika diinginkan"),("Bahan Kering","2 sendok teh baking powder"),("Bahan Kering","1 sendok teh soda kue"),("Bahan Kering","¼ sendok teh garam laut"),("Bahan Basah","½ cangkir + 2 sdm pisang tumbuk yang sangat matang, sekitar 2 pisang ukuran sedang"),("Bahan Basah","¼ cangkir sirup maple"),("Bahan Basah","¼ cangkir saus apel tanpa gula"),("Bahan Basah","1 sdm penuh parutan kulit lemon, sekitar 1 lemon ukuran sedang"),("Bahan Basah","1 cangkir susu kedelai tanpa pemanis atau susu almond atau mete"),("Bahan Basah","2 cangkir bayam muda (2 cangkir sebelum dicincang) dicincang halus dalam food processor atau blender, tetapi tidak dihaluskan menjadi puree")],
["Panaskan oven Anda terlebih dahulu hingga 375 derajat F.","Tumbuk pisang dalam mangkuk pencampur besar lalu masukkan semua bahan basah lainnya dan aduk rata. Lalu masukkan bahan kering ke dalam mangkuk yang sama dan aduk hingga tercampur tanpa mengaduk berlebihan.","Isi cetakan muffin mini Anda, hampir penuh, sisakan sedikit ruang untuk mengembang. Anda akan mendapatkan 36 muffin mini.","Panggang selama 13-16 menit, atau hingga tusuk gigi yang ditusukkan di tengah muffin keluar bersih. Keluarkan dari oven dan biarkan dingin selama 10 menit sebelum dikeluarkan dari cetakan muffin dan selamat menikmati."],
["** Jika Anda tidak memiliki tepung beras cokelat, atau tepung oat, masukkan satu cangkir beras dan satu cangkir oat ke dalam blender berkecepatan tinggi dan proses hingga mencapai konsistensi seperti tepung. Ini bisa memakan waktu 30-60 detik tergantung mesin Anda. Gunakan pisang yang sangat matang. Semakin banyak bintik cokelat, semakin baik untuk mendapatkan kemanisan alami semaksimal mungkin. Bayam muda segar lebih disukai daripada yang beku. Saya menemukan bayam segar memiliki rasa yang lebih ringan daripada yang beku dan paling enak jika digunakan dalam suguhan manis. Jangan menghaluskan bayam menjadi puree atau seluruh muffin akan berubah menjadi hijau. Ini dapat membuat anak kecil tidak berselera, jadi saya suka mencincangnya halus agar muffin tetap berwarna kekuningan. Jika Anda tidak memiliki bayam, Anda juga dapat menggunakan kangkung kale. Ingat saja bahwa kale memiliki rasa yang lebih kuat, jadi Anda mungkin ingin mengurangi jumlahnya sedikit. Karena muffin sehat ini hampir tidak mengandung lemak, hindari cup kertas roti, atau pastikan menyemprotnya dengan semprotan antilengket agar tidak lengket pada kertas. Gunakan cetakan muffin antilengket, ATAU pastikan mengolesi cetakan dengan lemak agar muffin Anda tidak lengket dan hancur. Biarkan muffin bayam pisang Anda dingin selama 5-10 menit setelah dikeluarkan dari oven, sebelum dikeluarkan dari cetakan muffin. Saya menggunakan cetakan muffin antilengket dan tidak perlu mengolesinya, dan muffin ini mudah keluar tanpa hancur sama sekali setelah masa pendinginan. Karena muffin ini sangat rendah gula, Anda dapat menambahkan ¼-1/3 cangkir keping cokelat (bebas susu sapi jika vegan) jika Anda perlu menyenangkan penyuka makanan yang lebih pilih-pilih. Preferensi kemanisan sepenuhnya tergantung pada apa yang Anda biasakan, dan ini cocok untuk kami tanpa keping cokelat, tetapi Anda yang paling mengenal keluarga Anda."],[]))
R.append((9430487,"Daging Sapi dan Brokoli Vegan",
"Daging sapi dan brokoli vegan yang mengenyangkan dibuat menggunakan soy curls untuk hidangan yang lebih baik daripada makanan pesan antar!",
"4 porsi","1 porsi",
["4 ons soy curls, sekitar setengah kantong merek Butler's","2 cangkir kaldu sayuran","4 cangkir kuntum brokoli",("Untuk saus","¼ cangkir kecap asin rendah natrium atau tamari untuk bebas gluten"),("Untuk saus","½ cangkir air"),("Untuk saus","2 sendok makan sirup maple"),("Untuk saus","3 siung bawang putih, dikupas + dicincang halus"),("Untuk saus","2 sendok teh jahe segar parut"),("Untuk saus","1 sendok makan tepung tapioka atau tepung maizena"),("Untuk saus","½ sendok teh serpihan cabai merah, opsional"),("Untuk penyajian","Mi bihun atau nasi cokelat"),("Untuk penyajian","daun bawang"),("Untuk penyajian","biji wijen")],
["Masukkan soy curls ke dalam mangkuk besar dan tutup dengan kaldu. Rendam selama sekitar 7-8 menit, aduk di pertengahan waktu agar semuanya terendam.","Sementara itu, kukus brokoli Anda dalam panci atau wajan berisi air selama 4-5 menit, hingga empuk saat ditusuk garpu tetapi masih sedikit renyah (atau tingkat kematangan yang Anda inginkan). Lalu tiriskan dan sisihkan.","Panaskan wajan besi cor atau wajan besar lainnya dengan api sedang-besar lalu angkat soy curls dari kaldu (sisihkan kaldunya) dan tumis kering soy curls selama 3-4 menit, sering diaduk, agar sedikit kecokelatan.","Sementara itu, masukkan semua bahan saus ke dalam mangkuk berisi sisa kaldu dan kocok hingga tercampur. Lalu masukkan saus dan brokoli ke dalam wajan berisi soy curls dan didihkan perlahan selama 2-3 menit agar saus sedikit mengental. Sajikan dengan nasi, mi, daun bawang, dan/atau biji wijen."],
["Aduk soy curls sesering mungkin saat menumis agar tidak lengket karena kita tidak menggunakan minyak dalam resep ini. Jika Anda tidak menghindari minyak, Anda dapat menggunakan satu sendok makan minyak wijen untuk menambah rasa.","Sisa makanan dapat disimpan di lemari es selama 2-3 hari dalam wadah tertutup."],[]))
R.append((9433642,"Donat Labu Vegan [Bebas Gluten + Bebas Minyak Juga]",
"Donat labu vegan ini penuh rasa labu, dibumbui kayu manis dan sangat lembap serta lezat.",
"12 donat","1 porsi",
[("Bahan Basah","1 cangkir puree labu"),("Bahan Basah","½ cangkir saus apel tanpa gula"),("Bahan Basah","¼ cangkir sirup maple"),("Bahan Kering","180 gram tepung oat bebas gluten (sekitar 1.5 cangkir)"),("Bahan Kering","75 gram gula kelapa tanpa pemurnian atau gula merah (sekitar ⅓ cangkir)"),("Bahan Kering","2 sendok teh kayu manis"),("Bahan Kering","1.5 sendok teh baking powder"),("Untuk Glasir (Opsional)","½ cangkir kurma tanpa biji, dipadatkan perlahan"),("Untuk Glasir (Opsional)","¾ cangkir air segar"),("Untuk Glasir (Opsional)","1.5 sendok teh kayu manis")],
["Panaskan oven terlebih dahulu hingga 350 derajat F.","Masukkan bahan basah ke dalam mangkuk besar dan aduk rata. Lalu masukkan bahan kering ke dalam mangkuk yang sama dan aduk hingga tercampur.","Bagi campuran ke cetakan donat antilengket Anda, cukup untuk membuat 12 donat. Panggang selama 18-20 menit, atau hingga kokoh saat disentuh, tetapi sedikit melesak saat ditekan perlahan dengan jari. Lalu keluarkan dari oven dan biarkan dingin setidaknya 10 menit sebelum dipindahkan ke rak pendingin.",("Glasir Opsional","Selagi donat mendingin, siapkan glasir. Masukkan kurma, air, dan kayu manis ke dalam blender dan proses hingga benar-benar halus. Lalu, pindahkan ke piring dangkal."),("Glasir Opsional","Ketika donat sudah dingin, celupkan ke dalam glasir dan letakkan dengan sisi glasir menghadap ke atas di rak pendingin Anda. Biarkan mengering dan selamat menikmati.")],
["Timbang tepung Anda jika memungkinkan, untuk hasil yang paling diinginkan. Gunakan cetakan donat silikon antilengket agar tidak perlu mengolesi cetakan dengan lemak, jika Anda menghindari minyak. Donat saya mudah keluar setelah dingin. Biarkan donat Anda dingin selama 10-15 menit sebelum mencoba mengeluarkannya dari cetakan. Jika donat masih panas, Anda berisiko mematahkannya. Biarkan donat labu Anda dingin di rak pendingin selama 10 menit sebelum diberi glasir. Jika Anda tidak memiliki blender yang bertenaga kuat atau kurma Anda sangat kering, rendam dalam air dingin selama 15-20 menit, sebelum diblender. Ini akan melunakkannya dan membantu menghancurkannya dengan lebih halus. Sisa donat akan tetap lembap dan segar dalam wadah tertutup pada suhu ruangan selama 2-3 hari, meskipun paling enak pada hari donat dibuat. Informasi nilai gizi tidak termasuk glasir opsional."],[]))
R.append((9437802,"Pasta Brokoli Asparagus",
"Hidangan pasta brokoli asparagus ini mengenyangkan, kaya rasa, dan siap dalam 30 menit atau kurang.",
"4 porsi","1 porsi",
["½ pon (8 ons) pasta penne, sekitar setengah bungkus kotak pasta standar","1 bawang bombai kuning, dicincang halus","5 siung bawang putih, dicincang halus","1 ikat asparagus, ujungnya dipotong dan dipotong 1 inci","4 cangkir kuntum brokoli","1 cangkir kaldu sayuran","½ cangkir susu nabati","1 sendok makan tepung tapioka atau tepung maizena","¼ sendok teh serpihan cabai merah, opsional, tetapi disarankan","¼ cangkir keju parmesan vegan","garam + merica secukupnya"],
["Didihkan sepanci besar air yang diberi banyak garam. Lalu masak pasta Anda sesuai petunjuk kemasan hingga pasta 'al dente'. Tiriskan tetapi sisihkan sebagian air rebusan pasta, dan sisihkan.","Sementara itu, gunakan wajan dalam untuk menumis bawang bombai dan bawang putih dengan 2-3 sendok makan air dengan api sedang hingga bening, sekitar 3-4 menit. Lalu masukkan asparagus dan brokoli, bumbui dengan garam dan merica, dan lanjutkan menumis hingga empuk, sekitar 6-8 menit.","Selagi sayuran dimasak, campurkan kaldu, susu, pati tapioka, dan serpihan cabai merah dalam mangkuk atau gelas ukur. Aduk rata lalu tuang saus ke dalam wajan berisi sayuran. Didihkan perlahan hingga mengental, sekitar 2-3 menit lalu matikan api.","Sekarang pasta Anda seharusnya sudah matang, jadi masukkan ke dalam wajan berisi saus dan sayuran bersama keju parmesan vegan, dan aduk rata.","Opsional: Untuk saus yang lebih encer, tambahkan sebagian air rebusan pasta yang Anda sisihkan ke dalam wajan dan aduk. (Sesuai selera Anda.)"],[],[]))
R.append((9439579,"Keju Vegan yang Bisa Diparut dan Meleleh [Pilihan Bebas Minyak]",
"Keju vegan yang meleleh dan bisa diparut seperti mozzarella!! Anda tidak akan percaya mata (atau lidah) Anda.",
"8 porsi","1 porsi",
["½ cangkir almond blanched atau kacang mete mentah atau biji bunga matahari","4 sendok makan tepung tapioka","2 sendok makan ragi nutrisi","1.5 sendok makan kappa carrageenan","1 sendok makan pasta miso putih","1 sendok makan cuka putih","½ sendok teh garam laut","¼ sendok teh bubuk bawang bombai","4 sendok makan minyak kelapa murni (refined), opsional, lihat catatan","1.5 cangkir air mendidih panas"],
["Rendam almond atau kacang mete Anda dalam air panas selama 15 menit lalu tiriskan.","Sementara itu, letakkan air tambahan di atas kompor atau dalam ketel untuk dididihkan. Anda memerlukan 1.5 cangkir air mendidih, jadi tambahkan sedikit lebih banyak untuk mengimbangi penguapan.","Temukan piring, mangkuk, atau wadah tahan panas (kaca, bukan plastik) yang dapat menampung sekitar 3 cangkir cairan dan letakkan di samping blender Anda.","Masukkan semuanya KECUALI air ke dalam blender Anda dan setelah air mendidih, masukkan 1.5 cangkir air mendidih ke dalam blender Anda, di atas semua bahan lainnya dan segera blender hingga halus.","Tuang campuran ke dalam piring tahan panas Anda dan dinginkan di lemari es selama 3 jam atau lebih lama, hingga padat.","Gunakan pisau mentega, atau spatula silikon untuk menyusuri tepi keju vegan Anda dan memisahkannya dari piring. (Lihat foto proses di atas sebagai gambaran.) Lalu balikkan di atas permukaan bersih, seperti talenan untuk mengeluarkannya dari piring.","Sekarang iris atau parut keju Anda untuk digunakan dalam berbagai hidangan."],
["Meskipun Anda memiliki blender berkecepatan tinggi, seperti Vitamix, untuk resep ini, saya menyarankan merendam almond atau kacang mete Anda. Melakukan hal itu akan membantu mereka diblender jauh lebih cepat sehingga Anda dapat dengan cepat menuang campuran sebelum keju mulai mengeras. Bergeraklah dengan cepat!! Begitu Anda menambahkan air mendidih ke blender, campuran akan mulai mengental. Segera tuang campuran ke dalam piring tahan panas setelah halus. Pastikan menggunakan almond blanched. Jika Anda tidak memiliki almond blanched, Anda dapat melakukan blanching almond utuh sendiri, dengan cukup mudah. Untuk minyak kelapa: Pastikan menggunakan yang REFINED saja karena yang unrefined memiliki rasa kelapa yang kuat yang tidak Anda inginkan dalam keju Anda. Untuk keju vegan meleleh bebas minyak: Lewati minyak kelapa dan ganti dengan ¼ cangkir air untuk melengkapi bagian cairan dalam resep. Saya telah menguji keju vegan ini dengan dan tanpa minyak (lihat tes keju vegan bebas minyak di atas) dan Anda benar-benar BISA melewatkannya. Jika Anda lebih suka menghindari kappa carrageenan, saya pernah membaca bahwa Anda dapat menggunakan jumlah dua kali lipat (dalam hal ini 3 sendok makan) agar-agar sebagai gantinya. Saya belum menguji dengan cara ini dan tidak dapat berbicara tentang cara parutan atau lelehannya, tetapi beberapa sumber menyatakan hasilnya berhasil, meskipun tidak sebaik kappa. Keju vegan meleleh Anda dapat disimpan di lemari es selama 5-7 hari. Atau bekukan (utuh atau parut) dalam wadah kedap udara yang aman untuk freezer atau kantong zip top hingga 3 bulan. Cara Melakukan Blanching Almond: Didihkan panci kecil air (cukup untuk menutupi almond). Setelah mendidih, masukkan almond dan rebus selama 1 menit. Lalu tiriskan dan bilas dengan air dingin untuk mendinginkannya, cukup agar bisa dipegang. Lalu pencet almond dan kulitnya akan terlepas dengan mudah. Resep terinspirasi dari mozzarella vegan melar saya dan metode diadaptasi dari Vegan Blueberry."],[]))
R.append((9439640,"Kue Kering Matcha Vegan",
"Kue kering matcha vegan ini lezat, dengan rasa yang beraroma tanah dan cerah serta tekstur yang lembut dan kenyal.",
"12 kue kering","1 porsi",
[("Bahan Kering","180 gram tepung oat, sekitar 1.5 cangkir"),("Bahan Kering","⅓ cangkir gula tebu"),("Bahan Kering","2 sendok teh bubuk matcha"),("Bahan Kering","1.5 sendok teh baking powder"),("Bahan Kering","⅛ sendok teh garam laut"),("Bahan Basah","3 sendok makan susu nabati"),("Bahan Basah","2 sendok makan saus apel tanpa gula"),("Bahan Basah","1 sendok teh ekstrak vanila murni")],
["Panaskan oven terlebih dahulu hingga 350℉/176℃ dan alasi loyang dengan kertas roti.","Masukkan semua bahan kering ke dalam mangkuk pencampur besar dan kocok hingga tercampur. Lalu masukkan bahan basah dan aduk hingga tidak ada bagian tepung yang tersisa.","Sendok adonan kue kering ke atas loyang Anda untuk membuat 12 kue kering. Lalu panggang dalam oven yang sudah dipanaskan selama 8-9 menit. Kue akan sangat lembut saat baru keluar dari oven tetapi akan mengeras saat dingin."],
["Timbang tepung Anda untuk hasil terbaik. Menyendok ke dalam cangkir takar dapat memadatkan tepung dan Anda bisa mendapatkan lebih dari yang diperlukan.","Gunakan baking powder yang aktif. Baking powder yang sudah dibuka di lemari dapur selama beberapa bulan dapat kehilangan keefektifannya.","Kue kering ini dapat disimpan 1-2 hari pada suhu ruangan, hingga 4 hari di lemari es atau hingga 3 bulan di freezer."],[]))
R.append((9440103,"Sup Tomat dan Stroberi Panggang",
"Sup tomat dan stroberi panggang ini memadukan rasa manis dan gurih dalam hidangan yang ringan dan menyegarkan.",
"4 porsi","1 porsi",
["2 pon tomat matang (dibelah dua atau empat, jenis apa pun yang Anda suka)","1 cangkir stroberi segar (dibuang tangkainya)","1 bawang bombai kuning (dibelah empat)","2 siung bawang putih (biarkan dengan kulitnya!)","1.5 cangkir kaldu sayuran","1 sendok makan cuka balsamic","1 sendok makan sirup maple","garam + merica (secukupnya)","basil (untuk hiasan)"],
["Panaskan oven terlebih dahulu hingga 400℉/204℃ dan alasi loyang dengan kertas roti.","Susun tomat, stroberi, bawang bombai dan bawang putih di atas loyang Anda dalam satu lapisan. Taburi dengan garam dan merica lalu panggang selama sekitar 20-22 menit, atau hingga sedikit berkaramel. Keluarkan dari oven.","Pindahkan sayuran dan stroberi yang sudah matang ke blender Anda dan tambahkan kaldu, cuka, dan sirup maple. Blender hingga halus, lalu cicipi garam dan merica dan sesuaikan jika perlu.","Sajikan dengan hiasan basil yang baru dicincang."],[],[]))
R.append((9440117,"Wafel Pisang Vegan",
"Nikmati kelezatan manis dan sehat dari wafel pisang vegan.",
"10 wafel","1 porsi",
["1 cangkir pisang tumbuk dari sekitar 2 pisang besar","1.25 cangkir susu almond atau susu nabati pilihan Anda","1 sendok teh ekstrak vanila murni","270 gram tepung gandum utuh, sekitar 2 cangkir disendok + diratakan","2 sendok teh baking powder"],
["Panaskan alat pembuat wafel Anda dengan api sedang-besar, atau sesuai petunjuk pabrikan.","Tumbuk pisang Anda dan masukkan ke dalam mangkuk pencampur besar bersama susu dan vanila. Aduk rata.","Lalu aduk tepung dan baking powder hingga tercampur, tanpa mengaduk berlebihan.","Masak wafel sesuai petunjuk pabrikan, sekitar 4-6 menit, atau hingga tingkat kematangan yang diinginkan tercapai."],
["Timbang tepung Anda untuk hasil terbaik. Jika menyendok dari kantong, Anda mungkin menggunakan terlalu banyak dan memerlukan lebih banyak cairan agar adonan mencapai konsistensi yang tepat.","Jika Anda tidak memiliki timbangan dapur, sendokkan tepung ke dalam cangkir takar dan gunakan pisau untuk meratakan kelebihannya.","Gunakan pisang yang sangat matang dan berbintik cokelat untuk kemanisan alami dan rasa terbaik.","Pastikan cetakan wafel Anda PANAS sebelum menuang adonan wafel agar tidak lengket.","Jangan membuka tutup terlalu cepat atau wafel Anda akan patah dan angkat tutup perlahan dan hati-hati untuk memeriksa apakah lengket.","Adonan wafel berikutnya matang sedikit lebih cepat daripada adonan pertama, jadi awasi dengan cermat.","Simpan sisa makanan di lemari es selama 3-4 hari atau dibekukan hingga 3 bulan."],[]))
